results={}
for i,x in ex.items():
 outcome,attempt,gap=notes[i]
 versions=[]
 for p in sorted((D/'sources').glob('html-'+i+'v*')):
  versions.append({'snapshot':str(p.relative_to(D)),'body_sha256':H(p/'body'),'receipt':str((p/'receipt.json').relative_to(D)),'depth':'retrieved; target passages extracted; not a complete proof audit'})
