# Read all structured inherited context, retain compact audit, do not mutate it.
context={}
for p in [D.parent/'ledger.json',D.parent.parent/'ledger.json',D.parent.parent/'prior-campaign-context.json']:
 o=json.loads(p.read_text());context[str(p)]={'sha256':H(p),'top_level_keys':list(o) if isinstance(o,dict) else 'array','read_in_full_by_json_parser':True}
(D/'outputs/context-audit.json').write_text(json.dumps(context,indent=2))
# Immutable HTTP receipt and body inventory.
