for p in sorted((D/'sources').glob('*/receipt.json')):
 o=json.loads(p.read_text());receipts.append({'path':str(p.relative_to(D)),**o})
(D/'outputs/http-receipts.json').write_text(json.dumps(receipts,indent=2))
print('20 results; receipts',len(receipts))
